import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { procedures } from "./procedures.ts";

const target = fileURLToPath(
  new URL("../../../contracts/api/procedures.json", import.meta.url),
);
const text = `${JSON.stringify(
  {
    $comment:
      "Generated by `pnpm contract:export` from apps/api/src/router.ts. Do not edit.",
    transport: "orpc-rpc-1",
    prefix: "/rpc",
    procedures: procedures(),
  },
  null,
  2,
)}\n`;

if (process.argv.includes("--check")) {
  const current = await readFile(target, "utf8").catch(() => "");
  if (current !== text) {
    console.error(
      "contracts/api/procedures.json is stale. Run `pnpm contract:export`.",
    );
    process.exitCode = 1;
  }
} else await writeFile(target, text);
